def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]

    # Find rectangular outlines whose interiors are uniformly a different color.
    for color in set(v for row in grid for v in row):
        for r1 in range(h - 2):
            for r2 in range(r1 + 2, h):
                for c1 in range(w - 2):
                    for c2 in range(c1 + 2, w):
                        if not (
                            all(grid[r1][c] == color for c in range(c1, c2 + 1))
                            and all(grid[r2][c] == color for c in range(c1, c2 + 1))
                            and all(grid[r][c1] == color for r in range(r1, r2 + 1))
                            and all(grid[r][c2] == color for r in range(r1, r2 + 1))
                        ):
                            continue

                        interior = {
                            grid[r][c]
                            for r in range(r1 + 1, r2)
                            for c in range(c1 + 1, c2)
                        }
                        if len(interior) != 1 or color in interior:
                            continue

                        ih, iw = r2 - r1 - 1, c2 - c1 - 1
                        fill = 7 if ih % 2 == 1 and iw % 2 == 1 else 2
                        for r in range(r1 + 1, r2):
                            for c in range(c1 + 1, c2):
                                out[r][c] = fill
    return out
